def _components(grid, bg):
    h,w=len(grid),len(grid[0]); seen=set(); out=[]
    for r in range(h):
        for c in range(w):
            if grid[r][c]==bg or (r,c) in seen: continue
            color=grid[r][c]; stack=[(r,c)]; seen.add((r,c)); cells=[]
            while stack:
                x,y=stack.pop(); cells.append((x,y))
                for a in range(max(0,x-1),min(h,x+2)):
                    for b in range(max(0,y-1),min(w,y+2)):
                        if (a,b) not in seen and grid[a][b]==color:
                            seen.add((a,b)); stack.append((a,b))
            rs=[x for x,y in cells]; cs=[y for x,y in cells]
            out.append({'color':color,'cells':cells,
                        'box':(min(rs),min(cs),max(rs),max(cs)),
                        'edge':any(x in (0,h-1) or y in (0,w-1) for x,y in cells)})
    return out

def _signature(cells):
    forms=[]
    for flip in (1,-1):
        for turn in range(4):
            pts=[]
            for r,c in cells:
                x,y=r,flip*c
                for _ in range(turn): x,y=y,-x
                pts.append((x,y))
            mr=min(x for x,y in pts); mc=min(y for x,y in pts)
            forms.append(tuple(sorted((x-mr,y-mc) for x,y in pts)))
    return min(forms)

def _is_l(o):
    r0,c0,r1,c1=o['box']
    return r1>r0 and c1>c0 and len(o['cells'])==(r1-r0+1)+(c1-c0+1)-1

def transform(grid):
    out=[row[:] for row in grid]
    counts={}
    for row in out:
        for v in row: counts[v]=counts.get(v,0)+1
    bg=max(counts,key=counts.get)
    objs=_components(out,bg)
    candidates=[]
    for key in objs:
        if not key['edge'] or not _is_l(key): continue
        r0,c0,r1,c1=key['box']
        # Objects inside the L's bounding rectangle act as shape examples.
        samples=[o for o in objs if o is not key and all(r0<=r<=r1 and c0<=c<=c1 for r,c in o['cells'])]
        for sample in samples:
            sig=_signature(sample['cells'])
            for target in objs:
                if target is key or target is sample: continue
                if all(r0<=r<=r1 and c0<=c<=c1 for r,c in target['cells']): continue
                if _signature(target['cells'])==sig:
                    candidates.append((len(sample['cells']),len(target['cells']),len(key['cells']),key,target))
    if candidates:
        _,_,_,key,target=max(candidates,key=lambda x:(x[0],x[1],x[2]))
        for r,c in target['cells']: out[r][c]=key['color']
    return out
